 "content": "def transform(grid):
    """Expand the colored markers into their fixed directional strokes."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    strokes = []  # (orientation, cells, marker color)

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                # Two-cell rightward trail, capped by a 1 one row above its end.
                cells = [(r, c + 1, 5), (r, c + 2, 5), (r - 1, c + 2, 1)]
                for rr, cc, v in cells:
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = v
            elif color == 2:
                # Five-cell horizontal bar ending at the original 2.
                cells = [(r, cc, 2 if cc == c - 4 or cc == c else 5)
                         for cc in range(c - 4, c + 1) if 0 <= cc < w]
                strokes.append(("h", r, cells, color))
            elif color == 3:
                # Four-cell vertical stroke extending downward.
                cells = [(rr, c, 3 if rr == r + 3 else 5)
                         for rr in range(r, r + 4) if 0 <= rr < h]
                strokes.append(("v", c, cells, color))
            elif color == 6:
                # Vertical stroke to the upper edge, with matching endpoint color.
                cells = [(rr, c, 6 if rr == 0 or rr == r else 5)
                         for rr in range(0, r + 1)]
                strokes.append(("v", c, cells, color))

    # Draw strokes; crossings between a horizontal 2-bar and vertical stroke
    # are marked with color 4, as in the demonstrations.
    for orient, _, cells, _ in strokes:
        for r, c, value in cells:
            out[r][c] = value
    horizontals = [(r, c) for orient, r, cells, _ in strokes if orient == "h" for r, c, _ in cells]
    verticals = [(r, c) for orient, c, cells, _ in strokes if orient == "v" for r, c, _ in cells]
    for r, c in horizontals:
        if (r, c) in set(verticals):
            out[r][c] = 4
    return out


if __name__ == "__main__":
    pass
